contracts/Greeter.vy.content:
# @version 0.3.10

greeting: public(String[64])
owner: public(immutable(address))


@external
def __init__(greeting_: String[64]):
    self.greeting = greeting_
    owner = msg.sender


@external
def set_greeting(greeting_: String[64]):
    assert msg.sender == owner, "Greeter: not the owner"
    self.greeting = greeting_
